import React, { useState, useEffect } from 'react';
import {
  TextField, Button, Container, Typography, Paper, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, Chip, Box, Alert,
  CssBaseline, useMediaQuery, Zoom, Grid, ThemeProvider, createTheme, Fade,
} from '@mui/material';
import { blue, green, red, grey } from '@mui/material/colors';

const theme = createTheme({
  palette: {
    primary: {
      main: blue[800],
    },
    secondary: {
      main: green[600],
    },
    background: {
      default: '#f0f2f5',
      paper: '#ffffff',
    },
    error: {
      main: red[700],
    },
    text: {
      primary: '#222222',
      secondary: '#555555',
    },
  },
  typography: {
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    h3: {
      fontWeight: 700,
      letterSpacing: '0.05em',
      color: blue[800],
    },
    h6: {
      fontWeight: 600,
      color: '#444',
    },
    button: {
      textTransform: 'none',
      fontWeight: 600,
      borderRadius: 6,
      padding: '12px 24px',
      boxShadow: 'none',
    },
  },
  shape: {
    borderRadius: 10,
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          transition: 'background-color 0.3s ease, box-shadow 0.3s ease',
          '&:hover': {
            boxShadow: '0 6px 20px rgba(0,0,0,0.15)',
            backgroundColor: blue[700],
          },
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          boxShadow: '0 10px 30px rgba(0,0,0,0.12)',
          padding: '28px',
          borderRadius: 10,
          backgroundColor: '#fff',
        },
      },
    },
    MuiTableCell: {
      styleOverrides: {
        root: {
          fontSize: 15,
          padding: '14px 18px',
        },
        head: {
          backgroundColor: blue[800],
          color: '#fff',
          fontWeight: 700,
          fontSize: 15,
          letterSpacing: '0.07em',
          position: 'sticky',
          top: 0,
          zIndex: 2,
        },
      },
    },
  },
});

function App() {
  const [website, setWebsite] = useState('');
  const [monitoringStatus, setMonitoringStatus] = useState('Idle');
  const [threatDetected, setThreatDetected] = useState(false);
  const [message, setMessage] = useState('');
  const [threatLogs, setThreatLogs] = useState([]);

  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const startMonitoring = async () => {
    if (!website) {
      setMessage('Please enter a website URL.');
      return;
    }
    setMessage('');
    try {
      const response = await fetch('http://127.0.0.1:5001/start_monitoring', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ website }),
      });
      const data = await response.json();
      if (response.ok) {
        setMessage(data.message);
        setMonitoringStatus('Monitoring');
      } else {
        setMessage(data.error || 'Failed to start monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  const stopMonitoring = async () => {
    try {
      const response = await fetch('http://127.0.0.1:5001/stop_monitoring', { method: 'POST' });
      if (response.ok) {
        setMonitoringStatus('Idle');
        setThreatDetected(false);
        setThreatLogs([]);
        setMessage('Monitoring stopped.');
      } else {
        setMessage('Failed to stop monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  useEffect(() => {
    setThreatLogs([]);

    let interval = null;

    if (monitoringStatus === 'Monitoring') {
      interval = setInterval(async () => {
        try {
          const response = await fetch('http://127.0.0.1:5001/status');
          const data = await response.json();
          setMonitoringStatus(data.status);
          setThreatDetected(data.threat_detected);

          const logsResponse = await fetch('http://127.0.0.1:5001/threat_logs');
          const logsData = await logsResponse.json();
          const cleanedLogs = logsData.map(log => {
            let cleanedWebsite = log.website;
            if (cleanedWebsite.startsWith('http://')) {
              cleanedWebsite = cleanedWebsite.slice(7);
            } else if (cleanedWebsite.startsWith('https://')) {
              cleanedWebsite = cleanedWebsite.slice(8);
            }
            return { ...log, website: cleanedWebsite };
          });
          setThreatLogs(cleanedLogs);
        } catch (error) {
          setMonitoringStatus('Error');
          setThreatDetected(false);
          setThreatLogs([]);
        }
      }, 5000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [monitoringStatus]);

  const getStatusColor = (status) => {
    switch (status) {
      case 'Monitoring':
        return 'primary';
      case 'Idle':
        return 'default';
      case 'Starting':
        return 'secondary';
      default:
        return 'default';
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4, pl: '2.5cm' }}>
        <Typography variant={isMobile ? 'h5' : 'h3'} align="center" sx={{ fontWeight: 'bold', mb: 3 }}>
          Cyber Threat Detection System
        </Typography>
        <Typography variant="h6" align="center" sx={{ mb: 4 }}>
          Real-time Website Cyber Threat Monitoring and Detection
        </Typography>
        <Grid container spacing={3}>
          <Grid item xs={12} md={5}>
            <Paper elevation={4} sx={{ p: 3, height: 280, display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
              <Box
                component="form"
                onSubmit={(e) => {
                  e.preventDefault();
                  startMonitoring();
                }}
                sx={{
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 2,
                }}
              >
                <TextField
                  label="Website URL"
                  variant="outlined"
                  fullWidth
                  value={website}
                  onChange={(e) => setWebsite(e.target.value)}
                  required
                />
                <Box sx={{ display: 'flex', gap: 2, mt: 1 }}>
                  <Button variant="contained" color="primary" type="submit" fullWidth>
                    Start Monitoring
                  </Button>
                  <Button variant="outlined" color="error" fullWidth onClick={stopMonitoring}>
                    Stop Monitoring
                  </Button>
                </Box>
              </Box>
              {message && (
                <Zoom in={Boolean(message)}>
                  <Alert severity="info" sx={{ mt: 2 }}>
                    {message}
                  </Alert>
                </Zoom>
              )}
              <Box sx={{ mt: 3, textAlign: 'center' }}>
                <Typography variant="h6" component="span" sx={{ fontWeight: 'medium' }}>
                  Status:
                </Typography>
                <Chip
                  label={monitoringStatus}
                  color={threatDetected ? 'error' : getStatusColor(monitoringStatus)}
                  sx={{ ml: 2, fontWeight: 'bold', fontSize: 16, px: 3, py: 0.5 }}
                />
                {threatDetected && (
                  <Fade in={threatDetected} timeout={700}>
                    <Alert severity="error" sx={{ mt: 3 }}>
                      Threat Detected on the website!
                    </Alert>
                  </Fade>
                )}
              </Box>
            </Paper>
          </Grid>
          <Grid item xs={12} md={7}>
            <Paper elevation={4} sx={{ p: 3, maxHeight: 480, overflowY: 'auto', width: '100%' }}>
              <Typography variant="h5" gutterBottom sx={{ mb: 3, position: 'sticky', top: 0, backgroundColor: '#fff', zIndex: 3 }}>
                Threat Detection Log
              </Typography>
              <TableContainer sx={{ maxHeight: 420 }}>
                <Table stickyHeader aria-label="threat detection log table" sx={{ minWidth: 900 }}>
                  <TableHead>
                    <TableRow>
                      <TableCell sx={{ position: 'sticky', top: 0, backgroundColor: blue[800], color: '#fff', zIndex: 4 }}>Timestamp</TableCell>
                      <TableCell sx={{ position: 'sticky', top: 0, backgroundColor: blue[800], color: '#fff', zIndex: 4 }}>Website</TableCell>
                      <TableCell sx={{ position: 'sticky', top: 0, backgroundColor: blue[800], color: '#fff', zIndex: 4 }}>Threat Name</TableCell>
                      <TableCell sx={{ position: 'sticky', top: 0, backgroundColor: blue[800], color: '#fff', zIndex: 4 }}>Message</TableCell>
                      <TableCell sx={{ position: 'sticky', top: 0, backgroundColor: blue[800], color: '#fff', zIndex: 4 }}>Solution</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {threatLogs.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={5} align="center" sx={{ fontStyle: 'italic' }}>
                          No threats detected yet.
                        </TableCell>
                      </TableRow>
                    ) : (
                      threatLogs.map((log) => (
                        <TableRow key={log.id} hover>
                          <TableCell>{log.timestamp}</TableCell>
                          <TableCell>{log.website}</TableCell>
                          <TableCell>{log.threat_name}</TableCell>
                          <TableCell>{log.message}</TableCell>
                          <TableCell>{log.solution}</TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Paper>
          </Grid>
        </Grid>
      </Container>
    </ThemeProvider>
  );
}

export default App;
